#!/usr/bin/env bash
# =============================================================================
#  First Leaf: one-time setup   (Protogen case studies P301 · P302 · P303)
#
#  Run:   bash ~/Downloads/setup.sh
#
#  Safe to run again: it skips anything already done and never overwrites a
#  project file that already exists. Every step prints ✓ (done) or ✗ (what went
#  wrong + how to fix it). It never asks you to make a decision.
#  Plain-language guide: docs/SETUP.md
# =============================================================================
set -u

PROJECT_NAME="first-leaf"
PROJECT_DIR="${FL_PROJECT_DIR:-$HOME/Projects/$PROJECT_NAME}"
REPO_DESC="First Leaf: a made-up investing app for first-time investors. Protogen case studies P301, P302, P303. Everything is fictional; not financial advice."
TEST_MODE="${FL_TEST_MODE:-0}"   # used only to test this script on non-Mac machines

FAILED=0
DONE_LINES=()
if [ -t 1 ]; then G=$'\033[32m'; R=$'\033[31m'; Y=$'\033[33m'; B=$'\033[1m'; N=$'\033[0m'; else G=; R=; Y=; B=; N=; fi
step() { printf "\n${B}%s${N}\n" "$1"; }
ok()   { printf "  ${G}✓${N} %s\n" "$1"; DONE_LINES+=("✓ $1"); }
note() { printf "  ${Y}!${N} %s\n" "$1"; }
bad()  { printf "  ${R}✗${N} %s\n    ${B}How to fix:${N} %s\n" "$1" "$2"; FAILED=1; DONE_LINES+=("✗ $1"); }
finish() {
  printf "\n${B}──────────────── Summary ────────────────${N}\n"
  for l in ${DONE_LINES[@]+"${DONE_LINES[@]}"}; do printf "  %s\n" "$l"; done
  if [ "$FAILED" = 1 ]; then
    printf "\n${R}${B}Setup stopped.${N} Fix the ✗ above, then run the same command again. It picks up where it left off.\n"
    exit 1
  fi
  printf "\n${G}${B}Setup complete.${N}\n\n"
  printf "${B}Next (about 2 minutes, in your browser):${N}\n"
  printf "  1. Go to https://vercel.com/new, pick the SAME Vercel account as Pelipper Post,\n"
  printf "     import ${B}%s${N}, leave every setting as it is, and click Deploy.\n" "$PROJECT_NAME"
  printf "  2. In VS Code: File → Open Folder… → %s\n" "$PROJECT_DIR"
  printf "     Open Claude Code and type ${B}/status${N}. Check it's the account you want billed (${B}/login${N} to switch).\n"
  printf "  3. Paste the Phase 0 prompt from the planning chat into Claude Code.\n\n"
  exit 0
}

printf "${B}First Leaf setup${N}  →  %s\n" "$PROJECT_DIR"

# ----------------------------------------------------------------------------- Mac check
step "1. Checking this is a Mac"
if [ "$(uname -s)" = "Darwin" ] || [ "$TEST_MODE" = 1 ]; then ok "Running on $( [ "$TEST_MODE" = 1 ] && echo "test machine" || sw_vers -productName 2>/dev/null) $( [ "$TEST_MODE" = 1 ] || sw_vers -productVersion 2>/dev/null)"
else bad "This script is for macOS." "Run it on your Mac."; finish; fi

# ----------------------------------------------------------------------------- Homebrew
step "2. Homebrew (installs the other tools)"
if ! command -v brew >/dev/null 2>&1; then
  for p in /opt/homebrew/bin/brew /usr/local/bin/brew; do [ -x "$p" ] && eval "$("$p" shellenv)" && break; done
fi
if command -v brew >/dev/null 2>&1; then
  ok "Homebrew is installed ($(brew --version 2>/dev/null | head -1))"
else
  note "Installing Homebrew. Type your Mac password below and press Return. Nothing shows while you type; that's normal."
  # Homebrew's installer won't ask for a password in no-questions mode, so unlock sudo first.
  if sudo -v && NONINTERACTIVE=1 /bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"; then
    for p in /opt/homebrew/bin/brew /usr/local/bin/brew; do [ -x "$p" ] && eval "$("$p" shellenv)" && break; done
    if ! grep -q 'brew shellenv' "$HOME/.zprofile" 2>/dev/null; then
      echo "eval \"\$($(command -v brew) shellenv)\"" >> "$HOME/.zprofile"
    fi
    ok "Homebrew installed"
  else
    bad "Homebrew install failed." "Run this script again. If it fails twice, paste the red text into the planning chat."; finish
  fi
fi

# ----------------------------------------------------------------------------- Git
step "3. Git"
if git --version >/dev/null 2>&1; then ok "Git works ($(git --version))"
else
  xcode-select --install >/dev/null 2>&1 || true
  bad "Git isn't set up yet." "A window called \"Install Command Line Developer Tools\" opened. Click Install, wait until it finishes, then run this script again."; finish
fi

# ----------------------------------------------------------------------------- Node
step "4. Node (runs the project and its checks)"
node_major() { node -v 2>/dev/null | sed -E 's/^v([0-9]+).*/\1/'; }
node_minor() { node -v 2>/dev/null | sed -E 's/^v[0-9]+\.([0-9]+).*/\1/'; }
# Vite 8 and TypeScript 6 need Node 22.18 or newer (or 24.12+), matching package.json "engines".
node_ok() {
  local M m; M="$(node_major)"; m="$(node_minor)"
  [ -n "$M" ] || return 1
  [ "$M" -gt 24 ] && return 0
  [ "$M" -eq 24 ] && [ "$m" -ge 12 ] && return 0
  [ "$M" -eq 22 ] && [ "$m" -ge 18 ] && return 0
  return 1
}
if node_ok; then ok "Node $(node -v) is installed"
else
  if command -v node >/dev/null 2>&1; then note "Node $(node -v) is too old. Updating it with Homebrew…"; NODE_CMD="upgrade"
  else note "Installing Node with Homebrew…"; NODE_CMD="install"; fi
  if brew "$NODE_CMD" node >/dev/null 2>&1 || brew install node >/dev/null 2>&1; then
    hash -r
    if node_ok; then ok "Node $(node -v) installed"
    else bad "Node is still older than 22.18 (or 24.12+) ($(node -v 2>/dev/null)). Another copy of Node may come first on your computer." "Paste this line into the planning chat and I'll give you the exact fix."; finish; fi
  else bad "Node install failed." "Run: brew install node   then run this script again."; finish; fi
fi

# ----------------------------------------------------------------------------- GitHub CLI
step "5. GitHub CLI"
if command -v gh >/dev/null 2>&1; then ok "GitHub CLI is installed ($(gh --version | head -1))"
else
  note "Installing the GitHub CLI with Homebrew…"
  if brew install gh >/dev/null 2>&1 && command -v gh >/dev/null 2>&1; then ok "GitHub CLI installed"
  else bad "GitHub CLI install failed." "Run: brew install gh   then run this script again."; finish; fi
fi

# ----------------------------------------------------------------------------- Claude Code
step "6. Claude Code"
if command -v claude >/dev/null 2>&1 || [ -x "$HOME/.local/bin/claude" ]; then
  ok "Claude Code is installed"
else
  note "Installing Claude Code (official installer)…"
  if curl -fsSL https://claude.ai/install.sh | bash >/dev/null 2>&1 && { command -v claude >/dev/null 2>&1 || [ -x "$HOME/.local/bin/claude" ]; }; then ok "Claude Code installed"
  else note "Couldn't install the claude command. That's fine if you use the Claude Code extension in VS Code."; fi
fi
note "Reminder: open Claude Code and type /status to check which account it uses (/login to switch). This script can't do that for you."

# ----------------------------------------------------------------------------- GitHub login
step "7. GitHub login"
if gh auth status >/dev/null 2>&1; then
  GH_USER="$(gh api user -q .login 2>/dev/null)"
  ok "GitHub CLI is logged in as ${GH_USER}"
else
  bad "GitHub CLI isn't logged in." "Run: gh auth login   (choose GitHub.com → HTTPS → Login with a web browser), then run this script again."; finish
fi
if gh auth setup-git >/dev/null 2>&1; then ok "Git uses your GitHub login for pushes"
else bad "Couldn't connect git to your GitHub login." "Run: gh auth setup-git   then run this script again."; finish; fi

if [ -z "$(git config --global user.name 2>/dev/null)" ]; then
  NAME="$(gh api user -q '.name // .login' 2>/dev/null)"; git config --global user.name "${NAME:-$GH_USER}"
  ok "Set your git name to \"$(git config --global user.name)\""
else ok "Git name is \"$(git config --global user.name)\""; fi
if [ -z "$(git config --global user.email 2>/dev/null)" ]; then
  GH_ID="$(gh api user -q .id 2>/dev/null)"; git config --global user.email "${GH_ID}+${GH_USER}@users.noreply.github.com"
  ok "Set your git email to GitHub's private address"
else ok "Git email is set"; fi
AUTHOR="$(git config --global user.name)"

# ----------------------------------------------------------------------------- Pelipper Post (read-only)
step "8. Finding Pelipper Post (read-only reference)"
PELIPPER=""
if [ -n "${FL_PELIPPER:-}" ] && [ -d "${FL_PELIPPER}" ]; then PELIPPER="$FL_PELIPPER"; fi
for c in "$HOME/Projects/pelipper-post" "$HOME/Developer/pelipper-post" "$HOME/Sites/pelipper-post" "$HOME/GitHub/pelipper-post" \
         "$HOME/Documents/GitHub/pelipper-post" "$HOME/Documents/Projects/pelipper-post" "$HOME/Documents/pelipper-post" "$HOME/Desktop/pelipper-post"; do
  [ -z "$PELIPPER" ] && [ -d "$c" ] && PELIPPER="$c"
done
if [ -z "$PELIPPER" ] && command -v mdfind >/dev/null 2>&1; then
  PELIPPER="$(mdfind "kMDItemFSName == 'pelipper-post' && kMDItemContentType == 'public.folder'" 2>/dev/null | grep -v '/Library/' | head -1)"
fi
if [ -n "$PELIPPER" ]; then ok "Found Pelipper Post at $PELIPPER (Claude Code may read it, never change it)"
else PELIPPER="$HOME/Projects/pelipper-post"; note "Pelipper Post wasn't found. Phase 0 will skip comparing with it. Nothing else is affected."; fi
case "$PELIPPER" in
  "$HOME"/*) PELIPPER_TILDE="~${PELIPPER#"$HOME"}"; PELIPPER_RULE="$PELIPPER_TILDE" ;;
  *)         PELIPPER_TILDE="$PELIPPER";            PELIPPER_RULE="/${PELIPPER}" ;;
esac

# ----------------------------------------------------------------------------- Project files
step "9. Project folder and files"
mkdir -p "$PROJECT_DIR" || { bad "Couldn't create $PROJECT_DIR." "Check the folder name, then run this script again."; finish; }
WRITER='
const zlib = require("zlib"), fs = require("fs"), path = require("path");
const dir = process.argv[1];
const b64 = fs.readFileSync(0, "utf8").replace(/\s+/g, "");
const files = JSON.parse(zlib.gunzipSync(Buffer.from(b64, "base64")).toString("utf8"));
const subs = { __GH_USER__: process.env.FL_GH_USER, __AUTHOR__: process.env.FL_AUTHOR, __PELIPPER_PATH__: process.env.FL_PELIPPER_TILDE,
               __PELIPPER_RULE__: process.env.FL_PELIPPER_RULE, __PELIPPER_ABS__: process.env.FL_PELIPPER_ABS };
let wrote = 0, kept = 0;
for (const [rel, b] of Object.entries(files)) {
  const p = path.join(dir, rel);
  if (fs.existsSync(p)) { kept++; continue; }
  fs.mkdirSync(path.dirname(p), { recursive: true });
  let text = Buffer.from(b, "base64").toString("utf8");
  for (const [k, v] of Object.entries(subs)) text = text.split(k).join(v || "");
  fs.writeFileSync(p, text); wrote++;
}
console.log(wrote + " " + kept + " " + Object.keys(files).length);
'
PAYLOAD_FILE="$(mktemp "${TMPDIR:-/tmp}/first-leaf-payload.XXXXXX")"
cat > "$PAYLOAD_FILE" <<'__FIRST_LEAF_PAYLOAD__'
