__FIRST_LEAF_PAYLOAD__
RESULT="$(FL_GH_USER="$GH_USER" FL_AUTHOR="$AUTHOR" FL_PELIPPER_TILDE="$PELIPPER_TILDE" FL_PELIPPER_RULE="$PELIPPER_RULE" FL_PELIPPER_ABS="$PELIPPER" \
  node -e "$WRITER" "$PROJECT_DIR" < "$PAYLOAD_FILE")"
rm -f "$PAYLOAD_FILE"
if [ -z "$RESULT" ]; then bad "Couldn't write the project files." "Paste the output above into the planning chat."; finish; fi
read -r WROTE KEPT TOTAL <<<"$RESULT"
if [ "$WROTE" -gt 0 ]; then ok "Wrote $WROTE project files (kept $KEPT that already existed)"; else ok "All $TOTAL project files already exist (left untouched)"; fi
SELF="${BASH_SOURCE[0]:-$0}"
if [ -f "$SELF" ] && [ ! -f "$PROJECT_DIR/scripts/setup.sh" ]; then cp "$SELF" "$PROJECT_DIR/scripts/setup.sh" && ok "Saved a copy of this script to scripts/setup.sh"; fi

cd "$PROJECT_DIR" || { bad "Couldn't open $PROJECT_DIR." "Run this script again."; finish; }
LEFT="$(grep -rlE '__(GH_USER|AUTHOR|PELIPPER_PATH|PELIPPER_RULE|PELIPPER_ABS)__' --exclude=setup.sh --exclude-dir=node_modules --exclude-dir=.git . 2>/dev/null)"
if [ -n "$LEFT" ]; then bad "Some files still have blank placeholders: $(echo $LEFT | tr '\n' ' ')" "Paste this line into the planning chat."; finish; else ok "Filled in your GitHub name, author name and the Pelipper Post path"; fi

# ----------------------------------------------------------------------------- Checks
step "10. Checking the data and the rules"
if node scripts/validate-data.mjs >/tmp/first-leaf-validate.log 2>&1; then ok "Data validator: $(tail -1 /tmp/first-leaf-validate.log)"
else cat /tmp/first-leaf-validate.log; bad "Data checks failed." "Don't edit anything. Paste the output above into the planning chat."; finish; fi
if node scripts/validator-selftest.mjs >/tmp/first-leaf-selftest.log 2>&1; then ok "Validator self-test: $(tail -1 /tmp/first-leaf-selftest.log)"
else tail -30 /tmp/first-leaf-selftest.log; bad "Validator self-test failed." "Paste the output above into the planning chat."; finish; fi
if node scripts/check-boundaries.mjs --selftest >/dev/null 2>&1; then ok "Folder-boundary check self-test passed"
else bad "Folder-boundary self-test failed." "Paste the output into the planning chat."; finish; fi

# ----------------------------------------------------------------------------- Git history
step "11. Git history"
if [ ! -d .git ]; then git init -q -b main && ok "Started a git repository (branch: main)"; else ok "Git repository already exists"; fi
if ! git rev-parse --verify -q HEAD >/dev/null; then
  git add -A
  git commit -q -F - <<'__MSG__'
[shared] Plan First Leaf: briefs, fictional data, validator and AI context docs

- BRIEF.md (shared foundation) and one self-contained brief per case study
- Seeded fictional data for all three case studies (three demo accounts), with a
  42-rule validator and a self-test that proves each rule fails on 65 broken datasets
- CLAUDE.md build rules, STATUS.md handoff doc, phase prompts, setup guide
- vercel.json pinned from the first commit; placeholder page until Phase 0

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_013qmfueTxNbgYWAT3e1h5vG
__MSG__
  if git rev-parse --verify -q HEAD >/dev/null; then ok "First commit created ($(git rev-parse --short HEAD))"
  else bad "Couldn't create the first commit." "Paste the output into the planning chat."; finish; fi
else
  ok "History already exists ($(git rev-list --count HEAD) commits); nothing to commit"
  [ -n "$(git status --porcelain)" ] && note "There are uncommitted changes in the project folder. Left them alone for Claude Code."
fi

# ----------------------------------------------------------------------------- GitHub repo
step "12. GitHub repository (public)"
if gh repo view "$GH_USER/$PROJECT_NAME" >/dev/null 2>&1; then
  ok "Repo github.com/$GH_USER/$PROJECT_NAME already exists"
  git remote get-url origin >/dev/null 2>&1 || { git remote add origin "https://github.com/$GH_USER/$PROJECT_NAME.git" && ok "Connected this folder to it"; }
  git fetch -q origin 2>/dev/null || true
  if git rev-parse --verify -q origin/main >/dev/null && [ "$(git rev-parse HEAD)" = "$(git rev-parse origin/main)" ]; then ok "GitHub is up to date"
  elif git push -q -u origin main 2>/tmp/first-leaf-push.log; then ok "Pushed to GitHub"
  else cat /tmp/first-leaf-push.log; bad "Couldn't push to GitHub." "A repo named $PROJECT_NAME may already exist with different history. Paste the output into the planning chat."; finish; fi
else
  if gh repo create "$PROJECT_NAME" --public --description "$REPO_DESC" --source . --remote origin --push >/tmp/first-leaf-create.log 2>&1; then
    ok "Created public repo github.com/$GH_USER/$PROJECT_NAME and pushed"
  else cat /tmp/first-leaf-create.log; bad "Couldn't create the GitHub repo." "Paste the output above into the planning chat."; finish; fi
fi

finish
